INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(71406430, 'Libromancer Doombroker', '书灵师·死亡经纪人', 'リブロマンサー・デスブローカー', 'Ritual Effect Monster', 'Fiend', 'DARK', 6, 2500, 2000, '「书灵师」卡降临。这个卡名的②③的效果1回合各能使用1次。 ①：使用场上的怪兽作仪式召唤的这张卡可以直接攻击。 ②：自己主要阶段才能发动。从卡组选1张「书灵师」陷阱卡在自己的魔法与陷阱区域盖放。 ③：这张卡给与对方战斗伤害时，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽回到持有者卡组。'),
(16312943, 'Libromancer Fire', '书灵师·炽火', 'リブロマンサー・ファイア', 'Effect Monster', 'Cyberse', 'FIRE', 4, 1800, 1800, '这个卡名的①②的效果1回合各能使用1次。 ①：把手卡1只仪式怪兽给对方观看才能发动。这张卡从手卡特殊召唤。 ②：这张卡特殊召唤成功的场合才能发动。从卡组把「书灵师·炽火」以外的1只「书灵师」怪兽加入手卡。'),
(88106656, 'Libromancer Fireburst', '书灵师·炽火爆裂侠', 'リブロマンサー・ファイアバースト', 'Ritual Effect Monster', 'Cyberse', 'FIRE', 7, 2800, 2800, '「书灵师」卡降临。 ①：使用场上的怪兽作仪式召唤的这张卡不会被战斗破坏，给与对方的战斗伤害变成2倍。 ②：这张卡在同1次的战斗阶段中最多2次可以向怪兽攻击。 ③：自己或者对方的怪兽的攻击宣言时，从自己墓地把1只「书灵师」仪式怪兽除外才能发动。这张卡的攻击力上升200。'),
(45001322, 'Libromancer Firestarter', '书灵师·炽火燃点侠', 'リブロマンサー・ファイアスターター', 'Ritual Effect Monster', 'Cyberse', 'FIRE', 3, 1800, 1800, '「书灵师」卡降临。 ①：使用场上的怪兽作仪式召唤的这张卡不会被效果破坏，不能用效果除外。 ②：只要攻击力未满3000的这张卡在怪兽区域存在，每次对方把卡的效果发动，这张卡的攻击力·守备力上升200。'),
(18890039, 'Libromancer First Appearance', '书灵师崛起', 'リブロマンサー・ライジング', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：作为这张卡的发动时的效果处理，可以把同名卡不在自己场上存在的1只「书灵师」怪兽从卡组加入手卡。 ②：自己主要阶段才能发动。等级合计直到变成仪式召唤的怪兽的等级以上为止，把自己的手卡·场上的怪兽解放，从手卡把1只「书灵师」仪式怪兽仪式召唤。'),
(46123974, 'Libromancer Geek Boy', '书灵师·极客少年', 'リブロマンサー・Gボーイ', 'Effect Monster', 'Psychic', 'WIND', 3, 800, 800, '这个卡名的①②的效果1回合各能使用1次。 ①：把手卡1只仪式怪兽给对方观看才能发动。这张卡从手卡特殊召唤。 ②：这张卡特殊召唤成功的场合才能发动。从卡组把1张「书灵师」魔法卡加入手卡。'),
(44889144, 'Libromancer Intervention', '书灵师介入', 'リブロマンサー・インターフェア', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：对方把魔法·陷阱·怪兽的效果发动时，以自己场上1只「书灵师」仪式怪兽为对象才能发动。那只怪兽回到持有者手卡，那个发动的效果无效。那之后，可以从自己的手卡·墓地选1只「书灵师」怪兽特殊召唤。'),
(82128978, 'Libromancer Magigirl', '书灵师·魔法少女', 'リブロマンサー・マジガール', 'Effect Monster', 'Spellcaster', 'WATER', 4, 600, 2100, '这个卡名的①②的效果1回合各能使用1次。 ①：把手卡1只仪式怪兽给对方观看才能发动。这张卡从手卡特殊召唤。 ②：对方回合才能发动。等级合计直到变成仪式召唤的怪兽的等级以上为止，把自己的手卡·场上的怪兽解放，从手卡把1只「书灵师」仪式怪兽仪式召唤。'),
(52707042, 'Libromancer Mystigirl', '书灵师·秘法少女', 'リブロマンサー・ミスティガール', 'Ritual Effect Monster', 'Fairy', 'LIGHT', 4, 1400, 2100, '「书灵师」卡降临。这个卡名的②的效果1回合只能使用1次。 ①：只要使用场上的怪兽作仪式召唤的这张卡在怪兽区域存在，自己场上的仪式怪兽不会成为对方怪兽的效果的对象。 ②：这张卡特殊召唤成功的场合，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽直到回合结束时攻击力变成0，效果无效化。'),
(84121302, 'Libromancer Origin Story', '书灵师本源', 'リブロマンサー・オリジン', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这个卡名的③的效果1回合只能使用1次。 ①：作为这张卡的发动时的效果处理，可以从卡组选「书灵师本源」以外的1张「书灵师」魔法·陷阱卡在自己场上盖放。 ②：自己场上的「书灵师」仪式怪兽的攻击力上升自身的等级×100。 ③：自己场上有仪式怪兽仪式召唤的场合，以对方场上1张魔法·陷阱卡为对象才能发动。那张卡破坏。'),
(14478717, 'Libromancer Prevented', '书灵师阻拦', 'リブロマンサー・プリベント', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：自己场上有「书灵师」怪兽存在的场合，以对方场上1只表侧表示怪兽为对象才能发动。这个回合，那只表侧表示怪兽不能作为融合·同调·超量·连接召唤的素材。 ②：自己·对方的结束阶段，「书灵师」仪式怪兽不在自己场上存在的场合发动。这张卡送去墓地。'),
(15590355, 'Libromancer Realized', '书灵师实体化', 'リブロマンサー・リアライズ', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：把手卡1只「书灵师」仪式怪兽给对方观看才能发动。把持有和给人观看的怪兽的等级相同等级的1只「炽火衍生物」（电子界族·炎·攻/守0）在自己场上特殊召唤。只要这个效果特殊召唤的衍生物在自己场上存在，自己不是「书灵师」怪兽不能特殊召唤。'),
(55818463, 'Lich Lord, King of the Underworld', '死王 巫妖大君', '死王リッチーロード', 'Effect Monster', 'Zombie', 'DARK', 6, 2400, 1200, '这张卡上级召唤的场合，解放的怪兽必须是暗属性怪兽。 ①：这张卡被效果解放送去墓地的场合发动。墓地的这张卡加入手卡。'),
(14318794, 'Life Absorbing Machine', '生命吸收装置', '生命吸収装置', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '每次自己的准备阶段，回复之前的那个自己的回合支付的基本分的一半。'),
(17178486, 'Life Equalizer', '生命转换', 'ライフチェンジャー', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '双方基本分有8000以上的相差的场合才能发动。双方基本分变成3000。'),
(36148308, 'Life Extreme', '生命的奇迹', '命の奇跡', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '地属性同调怪兽才能装备。 ①：只在装备怪兽和对方怪兽进行战斗的伤害计算时，那只对方怪兽的攻击力下降1500。 ②：1回合1次，怪兽的表示形式变更的场合，以场上1张卡为对象才能发动。那张卡破坏。 ③：这张卡从魔法与陷阱区域送去墓地的场合，把自己场上1只「动力工具」同调怪兽解放才能发动。从额外卡组把1只「生命激流龙」当作同调召唤作特殊召唤。'),
(83589191, 'Life Hack', '生命入侵', 'ライフハック', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时变成和对方基本分数值相同，这个回合对方受到的全部伤害变成一半。 ②：自己主要阶段把墓地的这张卡除外，以场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时变成和自己基本分数值相同，这个回合对方受到的全部伤害变成一半。'),
(38105306, 'Life Shaver', '逐渐削减的生命', '削りゆく命', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：「逐渐削减的生命」在自己场上只能有1张表侧表示存在。 ②：对方结束阶段发动。给这张卡放置1个指示物。 ③：这张卡有指示物放置中的场合，自己·对方的主要阶段以及战斗阶段才能发动。这张卡送去墓地。那之后，对方尽可能选最多有这张卡放置的指示物数量的手卡丢弃。'),
(25165047, 'Life Stream Dragon', '生命激流龙', 'ライフ・ストリーム・ドラゴン', 'Synchro Tuner Monster', 'Dragon', 'EARTH', 8, 2900, 2400, '调整＋「动力工具龙」 ①：这张卡同调召唤成功时才能发动。自己基本分变成4000。 ②：只要这张卡在怪兽区域存在，自己受到的效果伤害变成0。 ③：这张卡被破坏的场合，可以作为代替把自己墓地1张装备魔法卡除外。'),
(76214441, 'Lifeforce Harmonizer', '生命协调体', 'ライフ・コーディネイター', 'Effect Monster', 'Psychic', 'WIND', 2, 800, 400, '对方把持有「给与基本分伤害的效果」的卡发动时，可以从手卡把这张卡丢弃让那个发动无效并破坏。'),
(89617515, 'Lifeless Leaffish', '摇海鱼 枯叶', '揺海魚デッドリーフ', 'Effect Monster', 'Fish', 'WATER', 4, 1500, 1600, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·反转召唤·特殊召唤时才能发动。从卡组把「摇海鱼 枯叶海龙」以外的1只鱼族怪兽送去墓地。 ②：把墓地的这张卡除外，以自己墓地3只鱼族怪兽为对象才能发动。那些怪兽回到卡组。那之后，自己抽1张。'),
(47297616, 'Light and Darkness Dragon', '光与暗之龙', '光と闇の竜', 'Effect Monster', 'Dragon', 'LIGHT', 8, 2800, 2400, '这张卡不能特殊召唤。这张卡的属性也当作「暗」使用。只要这张卡在场上表侧表示存在，效果怪兽的效果·魔法·陷阱卡的发动无效。每次这个效果把卡的发动无效，这张卡的攻击力·守备力下降500。这张卡被破坏送去墓地时，选择自己墓地存在的1只怪兽发动。自己场上的卡全部破坏。选择的1只怪兽在自己场上特殊召唤。'),
(19652159, 'Light and Darkness Dragonlord', '光与暗之龙王', '光と闇の竜王', 'Fusion Monster', 'Dragon', 'LIGHT', 10, 3400, 3000, '龙族·光属性·8星怪兽＋龙族·暗属性·8星怪兽 这张卡不用融合召唤不能特殊召唤。 ①：只要这张卡在怪兽区域存在，这张卡的属性也当作「暗」使用。 ②：怪兽的效果·魔法·陷阱卡发动时发动（同一连锁上最多1次）。这张卡的攻击力·守备力下降1000，那个发动无效。 ③：这张卡被对方破坏的场合，以自己墓地1只龙族怪兽为对象才能发动。那只怪兽特殊召唤。'),
(73206827, 'Light Barrier', '光之结界', '光の結界', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：自己准备阶段发动。进行1次投掷硬币，里出现的场合，这张卡的②③的效果直到下次的自己准备阶段无效。 ②：自己的「秘仪之力」怪兽的召唤·反转召唤·特殊召唤时发动的效果不进行投掷硬币而选里表的其中1个适用。 ③：自己的「秘仪之力」怪兽战斗破坏对方怪兽的场合发动。自己基本分回复那只破坏的怪兽的原本攻击力的数值。'),
(21251800, 'Light Bringer Lucifer', '带来光明的使者 路西法', '光をもたらす者 ルシファー', 'Normal Monster', 'Fairy', 'DARK', 6, 2600, 1800, '吾乃君临至高玉座统治天地者…要有光！'),
(61399402, 'Light Dragon @Ignister', '光龙＠伊格尼斯者', 'ライトドラゴン＠イグニスター', 'XYZ Monster', 'Cyberse', 'LIGHT', 4, 2300, 1500, '4星怪兽×2 这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡1个超量素材取除才能发动。选最多有自己场上的「@火灵天星」怪兽数量的对方场上的表侧表示怪兽破坏。 ②：这张卡以外的自己的电子界族怪兽给与对方战斗伤害时才能发动。从自己墓地选1只连接怪兽特殊召唤。 ③：自己场上的怪兽被效果破坏的场合，可以作为代替把这张卡1个超量素材取除。'),
(54766667, 'Light Effigy', '圣构体', 'ホーリーフレーム', 'Effect Monster', 'Fairy', 'LIGHT', 4, 1500, NULL, '光属性的通常怪兽祭品召唤的场合，这1只怪兽可以作为2只的数量的祭品。'),
(25132288, 'Light End Dragon', '光辉终结龙', 'ライトエンド・ドラゴン', 'Synchro Monster', 'Dragon', 'LIGHT', 8, 2600, 2100, '调整＋调整以外的光属性怪兽1只以上 这张卡进行战斗的场合，怪兽的攻击宣言时才能发动。这张卡的攻击力·守备力下降500，和这张卡进行战斗的对方怪兽的攻击力·守备力直到结束阶段时下降1500。'),
(35614780, 'Light End Sublimation Dragon', '光与升华之龙', '光と昇華の竜', 'Effect Monster', 'Dragon', 'LIGHT', 8, 2600, 2100, '这个卡名的①②③的效果1回合各能使用1次。 ①：从额外卡组把1只龙族·8星怪兽除外才能发动。这张卡从手卡特殊召唤。这个回合，自己不是龙族怪兽不能特殊召唤。 ②：自己主要阶段才能发动。自己的手卡·场上的怪兽作为融合素材，把1只融合怪兽融合召唤。 ③：对方怪兽的攻击宣言时才能发动。这张卡的攻击力·守备力下降500，那只对方怪兽的攻击力下降1500。'),
(30913809, 'Light Force', '光之波动', '光の波動', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的③的效果1回合只能使用1次。 ①：自己准备阶段，自己的场地区域没有「光之结界」存在的场合发动。进行1次投掷硬币，里出现的场合，这张卡的②③的效果直到下次的自己准备阶段无效化。 ②：自己场上的天使族怪兽的攻击力·守备力上升300。 ③：丢弃1张手卡才能发动。把2只卡名不同的「秘仪之力」怪兽从卡组加入手卡。这个回合，自己不是「秘仪之力」怪兽不能特殊召唤。'),
(11471117, 'Light Laser', '光之抹杀剑', 'ライトイレイザー', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '光属性·战士族才能装备。和装备怪兽进行战斗的怪兽在那个伤害步骤结束时从游戏中除外。'),
(52253888, 'Light Law Medium', '光之法理灵媒', 'ライトローミディアム', 'Effect Monster', 'Fairy', 'LIGHT', 2, 400, 300, '①：对方战斗阶段开始时，以对方场上的攻击表示怪兽任意数量为对象才能发动。只要这张卡在自己的怪兽区域存在，这个回合，作为对象的怪兽可以攻击的场合，必须向这张卡作出攻击。 ②：1回合1次，这张卡和对方的攻击表示怪兽进行战斗的攻击宣言时才能发动。那次攻击无效，给与对方那只对方怪兽的原本攻击力一半数值的伤害。'),
(83027236, 'Light of Destruction', '破坏之光', 'ライト・オブ・デストラクション', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '对方的效果从对方卡组让卡送去墓地时，从对方卡组上面把3张卡送去墓地。'),
(62867251, 'Light of Intervention', '神圣光辉', '聖なる輝き', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '只要这张卡在场上存在，不能把怪兽盖放。此外，把怪兽盖放的场合必须变成表侧守备表示。'),
(44595286, 'Light of Judgment', '裁决之光', '裁きの光', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：场上有「天空的圣域」存在的场合从手卡把1只光属性怪兽丢弃去墓地才能发动。从以下效果选1个适用。 ●把对方手卡确认，从那之中选1张卡送去墓地。 ●选对方场上1张卡送去墓地。'),
(2362787, 'Light of Redemption', '救援光', '救援光', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：支付800基本分，以除外的1只自己的光属性怪兽为对象才能发动。那只怪兽加入手卡。'),
(72554664, 'Light of the Branded', '烙印之光', '烙印の光', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己·对方的场上·墓地1只融合怪兽为对象才能发动。那只怪兽回到额外卡组。那之后，可以选自己墓地的「阿不思的落胤」和对方墓地的怪兽各1只在持有者场上特殊召唤。'),
(35577420, 'Light Spiral', '光之回弹', 'ライト・リサイレンス', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '每次名字带有「光道」的怪兽的效果从自己卡组把卡送去墓地，从对方卡组上面把1张卡从游戏中除外。'),
(82616239, 'Light Water Dragon', '超轻水合龙', 'ライトウォーター・ドラゴン', 'Effect Monster', 'Sea Serpent', 'WATER', 4, 1400, 1300, '这个卡名在规则上当作「水龙」使用。这个卡名的效果1回合只能使用1次。 ①：把场上的这张卡除外才能发动。从卡组把3只5星以下而水·风属性的恐龙族怪兽守备表示特殊召唤。这个效果特殊召唤的怪兽的效果无效化。这个效果的发动后，直到回合结束时自己不是恐龙族·海龙族怪兽不能从额外卡组特殊召唤。'),
(83880087, 'Light Wing Shield', '弯月罩', 'ムーンバリア', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：怪兽的攻击无效时，可以从以下效果选择1个发动。 ●变成这个回合的结束阶段。 ●以自己场上1只「希望皇 霍普」超量怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时变成原本攻击力的2倍。 ②：自己场上的「希望皇 霍普」超量怪兽把超量素材1个取除来让效果发动的场合，可以作为取除的超量素材的代替而把墓地的这张卡除外。'),
(53341729, 'Light-Imprisoning Mirror', '吸入闪光的魔镜', '閃光を吸い込むマジック・ミラー', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '只要这张卡在场上存在，场上·墓地发动的光属性怪兽的效果无效化。'),
(37231841, 'Lighten the Load', '轻量化', '軽量化', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '将手卡1只7星以上的怪兽加入卡组并且洗切，之后抽1张卡。这个效果1回合只能发动1次。'),
(49587034, 'Lightforce Sword', '光之封札剑', '光の封札剣', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方手卡随机选1张里侧表示除外。这张卡的发动后，用对方回合计算的第4回合的对方准备阶段，那张卡回到对方手卡。'),
(55226821, 'Lightning Blade', '闪电之剑', '稲妻の剣', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '战士族才可以装备。装备的怪兽的攻击力上升800。场上的全部水属性怪兽的攻击力下降500。'),
(22653490, 'Lightning Chidori', '电光千鸟', '電光千鳥', 'XYZ Monster', 'Thunder', 'WIND', 4, 1900, 1600, '风属性4星怪兽×2 这张卡超量召唤成功时，选择对方场上盖放的1张卡回到持有者卡组最下面。此外，1回合1次，把这张卡1个超量素材取除才能发动。选择对方场上表侧表示存在的1张卡回到持有者卡组最上面。'),
(27671321, 'Lightning Conger', '雷鳗', '雷ウナギ', 'Normal Monster', 'Thunder', 'WATER', 3, 350, 750, '传说中由小电鳗能够进化而成为雷电鳗。'),
(45023678, 'Lightning Punisher', '闪电处刑人', 'ライトニングパニッシャー', 'Effect Monster', 'Thunder', 'DARK', 7, 2600, 1600, '连锁积累有3个的场合，把对方场上1张卡破坏。同1组连锁上有复数次同名卡的效果发动的场合，这个效果不能发动。'),
(40672993, 'Lightning Rod Lord', '避雷神', '避雷神', 'Effect Monster', 'Thunder', 'LIGHT', 4, 1800, 100, '①：只要这张卡在怪兽区域存在，双方在主要阶段1内不能把魔法卡发动。'),
(14532163, 'Lightning Storm', '闪电风暴', 'ライトニング・ストーム', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上没有表侧表示卡存在的场合，可以从以下效果选择1个发动。 ●对方场上的攻击表示怪兽全部破坏。 ●对方场上的魔法·陷阱卡全部破坏。'),
(49389523, 'Lightning Tricorn', '闪电三角兽', 'ライトニング・トライコーン', 'Synchro Monster', 'Beast', 'LIGHT', 8, 2800, 2000, '调整＋调整以外的兽族怪兽1只以上 这张卡被对方破坏的场合，可以选择自己墓地存在的1只「雷电独角兽」或者「流电双角兽」在自己场上特殊召唤。'),
(69162969, 'Lightning Vortex', '闪电旋涡', 'ライトニング・ボルテックス', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：丢弃1张手卡才能发动。对方场上的表侧表示怪兽全部破坏。'),
(87259077, 'Lightning Warrior', '闪电战士', 'ライトニング・ウォリアー', 'Synchro Monster', 'Warrior', 'LIGHT', 7, 2400, 1200, '调整＋调整以外的怪兽1只以上 这张卡战斗破坏对方怪兽送去墓地时，给与对方基本分对方手卡数量×300的数值的伤害。'),
(89185742, 'Lightning, Dragon Ruler of Drafts', '风征龙－雷霆', '風征竜－ライトニング', 'Effect Monster', 'Dragon', 'WIND', 3, 500, 1800, '这个卡名的效果1回合只能使用1次。 ①：把1只龙族或风属性的怪兽和这张卡从手卡丢弃才能发动。从卡组把1只「岚征龙-飙龙」特殊召唤。这个效果特殊召唤的怪兽在这个回合不能攻击。'),
(99365553, 'Lightpulsar Dragon', '光脉冲星龙', 'ライトパルサー・ドラゴン', 'Effect Monster', 'Dragon', 'LIGHT', 6, 2500, 1500, '这张卡可以把自己墓地的光属性和暗属性的怪兽各1只从游戏中除外，从手卡特殊召唤。此外，可以把手卡的光属性和暗属性的怪兽各1只送去墓地，并把这张卡从自己墓地特殊召唤。这张卡从场上送去墓地时，可以选择自己墓地1只龙族·暗属性·5星以上的怪兽特殊召唤。'),
(38737148, 'Lightray Daedalus', '光芒使者 泰达路斯', 'ライトレイ ダイダロス', 'Effect Monster', 'Sea Serpent', 'LIGHT', 7, 2600, 1500, '这张卡不能通常召唤。自己墓地的光属性怪兽是4只以上的场合才能特殊召唤。1回合1次，选择场上2张卡和1张场地魔法卡才能发动。选择的卡破坏。'),
(30126992, 'Lightray Diabolos', '光芒使者 迪亚波罗斯', 'ライトレイ ディアボロス', 'Effect Monster', 'Dragon', 'LIGHT', 7, 2800, 1000, '这张卡不能通常召唤。自己墓地的光属性怪兽是5种类以上的场合可以特殊召唤。1回合1次，可以把自己墓地1只光属性怪兽从游戏中除外，选择对方场上盖放的1张卡确认，回到持有者卡组最上面或者最下面。'),
(4722253, 'Lightray Gearfried', '光芒使者 基亚·弗里德', 'ライトレイ ギア・フリード', 'Effect Monster', 'Warrior', 'LIGHT', 8, 2800, 2200, '这张卡不能通常召唤。自己墓地的光属性怪兽是5种类以上的场合才能特殊召唤。自己场上表侧表示存在的怪兽只有战士族的场合，可以把自己墓地1只战士族怪兽从游戏中除外，魔法·陷阱卡的发动无效并破坏。这个效果1回合只能使用1次。'),
(27407330, 'Lightray Grepher', '光芒使者 格雷法', 'ライトレイ グレファー', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1700, 1600, '这张卡可以从手卡丢弃1只5星以上的光属性怪兽，从手卡特殊召唤。此外，1回合1次，可以通过从手卡丢弃1只光属性怪兽，卡组1只光属性怪兽从游戏中除外。'),
(82579942, 'Lightray Madoor', '光芒使者 魔道士', 'ライトレイ マドール', 'Effect Monster', 'Spellcaster', 'LIGHT', 6, 1200, 3000, '从游戏中除外的自己的光属性怪兽是3只以上的场合，这张卡可以从手卡特殊召唤。这张卡1回合只有1次不会被战斗破坏。'),
(91349449, 'Lightray Sorcerer', '光芒使者 巫师', 'ライトレイ ソーサラー', 'Effect Monster', 'Spellcaster', 'LIGHT', 6, 2300, 2000, '这张卡不能通常召唤。从游戏中除外的自己的光属性怪兽是3只以上的场合才能特殊召唤。1回合1次，可以选择从游戏中除外的1只自己的光属性怪兽回到卡组，选择场上表侧表示存在的1只怪兽从游戏中除外。这个效果发动的回合，这张卡不能攻击。'),
(55501446, 'Lightserpent', '光之海蛇', 'ライト・サーペント', 'Effect Monster', 'Reptile', 'LIGHT', 3, 1200, 800, '这张卡从手卡送去墓地的场合，这张卡可以从墓地特殊召唤。这张卡不能作为同调素材。'),
(10515412, 'Lightstorm Dragon', '光明风暴龙', 'ライトストーム・ドラゴン', 'Synchro Monster', 'Dragon', 'LIGHT', 9, 2700, 3000, '调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤的场合，以最多有自己墓地的通常怪兽数量＋1张的场上的魔法·陷阱卡为对象才能发动。那些卡破坏。 ②：这张卡被战斗·效果破坏的场合，以自己墓地1张魔法·陷阱卡为对象才能发动。那张卡在自己场上盖放。这个效果盖放的卡在自己场上没有通常怪兽存在的场合不能发动。'),
(25218587, 'Lightsworn Aegis', '光道埃癸斯', 'ライトロード・アイギス', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以最多有自己场上的「光道」怪兽数量的对方场上的表侧表示卡为对象才能发动。那些卡的效果直到回合结束时无效。 ②：这张卡从卡组送去墓地的场合才能发动。这张卡在自己场上盖放。'),
(22201234, 'Lightsworn Barrier', '光道防护罩', 'ライトロード・バリア', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '自己场上表侧表示存在的名字带有「光道」的怪兽成为攻击对象时，可以从自己卡组上面把2张卡送去墓地让1只对方怪兽的攻击无效。'),
(59481082, 'Lightsworn Dragonling', '光道之龙', '光道の龍', 'Effect Monster', 'Dragon', 'LIGHT', 4, 1500, 1300, '这个卡名的①②③的效果1回合各能使用1次。 ①：自己墓地有「光道」怪兽存在的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡特殊召唤的场合才能发动。从卡组把「光道之龙」以外的1张「光道」卡送去墓地。 ③：这张卡被送去墓地的场合才能发动。从卡组把1只攻击力3000/守备力2600的龙族怪兽加入手卡。'),
(66194206, 'Lightsworn Judgment', '光道之裁决', 'ライトロードの裁き', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：这张卡回到卡组最上面。 ②：这张卡被「光道」怪兽的效果从卡组送去墓地的场合才能发动。从卡组把1只「裁决之龙」加入手卡。'),
(30502181, 'Lightsworn Sabre', '光道细剑', 'ライトロード・レイピア', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '名字带有「光道」的怪兽才能装备。装备怪兽的攻击力上升700。这张卡从卡组被送去墓地时，可以把这张卡给自己场上存在的1只名字带有「光道」的怪兽装备。'),
(52665542, 'Lightsworn Sanctuary', '光道的神域', 'ライトロードの神域', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：1回合1次，把手卡1只「光道」怪兽送去墓地，以那只怪兽以外的自己墓地1只「光道」怪兽为对象才能发动。作为对象的怪兽加入手卡。 ②：只要这张卡在魔法与陷阱区域存在，每次从自己卡组有卡被送去墓地，给这张卡放置1个光指示物。 ③：自己场上的「光道」卡被效果破坏的场合，可以作为代替把破坏的「光道」卡每1张2个自己场上的光指示物取除。'),
(78845026, 'Lightwave Tuning', '电光调整', 'ライトニング・チューン', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上表侧表示存在的1只4星的光属性怪兽发动。选择怪兽只要在场上表侧表示存在当作调整使用。'),
(65289956, 'Like the Diabell', '猛如迪亚贝尔', 'ライク・ザ・ディアベル', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：魔法·陷阱卡被效果送去墓地的场合才能发动。从自己的手卡·墓地把1张魔法·陷阱卡在自己场上盖放。这个效果盖放的卡在这个回合不能发动。 ②：自己主要阶段，从自己墓地把包含这张卡的3张魔法·陷阱卡除外才能发动。从自己的手卡·墓地把1只「迪亚贝尔」怪兽特殊召唤。'),
(72233469, 'Lil-la Rap', '璃拉说唱', 'リィラップ', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的效果在同一连锁上只能发动1次。 ①：1回合1次，自己从墓地把怪兽特殊召唤的场合才能发动。对方失去1000基本分，自己回复500基本分。'),
(23898021, 'Lilith, Lady of Lament', '恶之魔娘 莉丽斯', '悪魔嬢リリス', 'Effect Monster', 'Fiend', 'DARK', 3, 2000, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：召唤的这张卡的原本攻击力变成1000。 ②：把自己场上1只暗属性怪兽解放才能发动。从卡组把3张通常陷阱卡给对方观看，对方从那之中随机选1张。那1张卡在自己场上盖放，剩下的卡回到卡组。这个效果在对方回合也能发动。'),
(68812773, 'Lillybot', '奥波美', 'オボミ', 'Effect Monster', 'Machine', 'LIGHT', 4, 500, 2000, '①：这张卡召唤·反转时，以自己墓地1只「轨道 7」为对象才能发动。那只怪兽表侧攻击表示或者里侧守备表示特殊召唤。 ②：1回合1次，把自己场上的机械族怪兽任意数量解放才能发动。把解放数量的「光子」怪兽或者「银河」怪兽从手卡特殊召唤。'),
(86607583, 'Limit Code', '限制代码', 'リミット・コード', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在决斗中只能发动1张。 ①：自己墓地有电子界族连接怪兽存在的场合才能把这张卡发动。那些怪兽数量的指示物给这张卡放置，从额外卡组把1只「码语者」怪兽特殊召唤，把这张卡当作装备卡使用给那只怪兽装备。这张卡从场上离开时那只怪兽破坏。 ②：自己结束阶段发动。这张卡1个指示物取除。不能取除的场合这张卡破坏。'),
(82324105, 'Limit Impulse', '对极限的冲动', '極限への衝動', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '把2张手卡送去墓地发动。在自己场上把2只「灵魂衍生物」（恶魔族·暗·1星·攻/守0）特殊召唤。这衍生物不能为上级召唤以外而解放。'),
(35014241, 'Limit Overdrive', '超限疾驰', 'リミットオーバー・ドライブ', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '「破限疾驰」在1回合只能发动1张。 ①：让自己场上1只同调怪兽调整和1只调整以外的同调怪兽回到额外卡组才能发动。和那2只怪兽的等级合计相同等级的1只同调怪兽无视召唤条件从额外卡组特殊召唤。'),
(27551, 'Limit Reverse', '限制苏生', 'リミット・リバース', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '从自己墓地选择1只攻击力1000以下的怪兽，攻击表示特殊召唤。那只怪兽变成守备表示时，那只怪兽和这张卡破坏。这张卡从场上离开时，那只怪兽破坏。那只怪兽破坏时这张卡破坏。'),
(92450185, 'Limiter Overload', '限速突破', 'リミッター・ブレイク', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：这张卡被送去墓地的场合发动。从自己的手卡·卡组·墓地选1只「高速战士」特殊召唤。'),
(23171610, 'Limiter Removal', '限制解除', 'リミッター解除', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：自己场上的全部机械族怪兽的攻击力直到回合结束时变成2倍。这个回合的结束阶段，这个效果适用中的怪兽破坏。'),
(52339733, 'Lindbloom', '龙胆花鳞虫', '竜胆ブルーム', 'Effect Monster', 'Wyrm', 'EARTH', 4, NULL, 1800, '①：这张卡在怪兽区域存在，自己怪兽和对方怪兽进行战斗的伤害计算时发动。直到伤害步骤结束时，进行战斗的各自怪兽的攻击力变成和各自守备力相同数值。'),
(29307554, 'Lineage of Destruction', '破坏神的系谱', '破壊神の系譜', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '把对方场上守备表示存在的怪兽破坏的回合，选择自己场上表侧表示存在的1只8星的怪兽发动。这个回合，选择怪兽在同1次的战斗阶段中可以作2次攻击。'),
(64238008, 'Linear Accelerator Cannon', '线性加农炮', 'リニアキャノン', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '把自己场上存在的1只怪兽作为祭品，给与对方基本分那只怪兽的原本攻击力一半数值的伤害。这张卡发动的场合，这个回合中不能发动其他魔法卡。'),
(70916046, 'Linear Equation Cannon', '一时炮固定式', '壱時砲固定式', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己·对方的战斗阶段，宣言1·2·3·4·5·6的其中任意数字才能发动。选对方场上1只效果怪兽，以下数值的合计数字和自己墓地的卡数量相同的场合，把最多有宣言的数字数量的卡从自己卡组上面送去墓地，选最多有送去墓地的数量的对方场上的卡回到持有者卡组。不是的场合，自己失去宣言的数字×500基本分。 ●选的怪兽的等级×宣言的数字 ●对方场上的卡数量'),
(24842059, 'Linguriboh', '连环古里波', 'リングリボー', 'Link Monster', 'Cyberse', 'DARK', NULL, 300, NULL, '4星以下的电子界族怪兽1只 这个卡名的①②的效果1回合各能使用1次。 ①：对方把陷阱卡发动时，把这张卡解放才能发动。那个效果无效并除外。 ②：这张卡在墓地存在的场合，把从额外卡组特殊召唤的自己场上1只「@火灵天星」怪兽解放才能发动。这张卡特殊召唤。这个效果在对方回合也能发动。'),
(7925734, 'Link Apple', '连接苹果', 'リンクアップル', 'Effect Monster', 'Cyberse', 'FIRE', 1, NULL, NULL, '这个卡名的效果1回合只能使用1次。 ①：把手卡的这张卡给对方观看才能发动。自己的额外卡组的里侧表示的卡随机选1张除外。除外的卡是连接怪兽的场合，这张卡特殊召唤。不是的场合，这张卡从手卡丢弃，自己从卡组抽1张。'),
(3567660, 'Link Back', '连接后退', 'リンク・バック', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以额外怪兽区域1只自己的连接怪兽为对象才能发动。那只自己怪兽的位置向作为那所连接区的自己的主要怪兽区域移动。那之后，可以把那只怪兽的连接标记数量的卡从自己卡组上面送去墓地。'),
(51335426, 'Link Bound', '反弹连接', 'バウンドリンク', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己的场上·墓地1只连接怪兽为对象才能发动。那只怪兽回到持有者的额外卡组，自己从卡组抽出那个连接标记的数量。那之后，选抽出数量的手卡用喜欢的顺序回到卡组下面。'),
(67231737, 'Link Bumper', '连接缓冲人', 'リンク・バンパー', 'Link Monster', 'Cyberse', 'EARTH', NULL, 1400, NULL, '电子界族怪兽2只 ①：1回合1次，这张卡所连接区的自己怪兽向对方的连接怪兽攻击的伤害步骤结束时才能发动。这次战斗阶段中，那只怪兽在通常攻击外加上可以向对方的连接怪兽作出最多有这张卡以外的自己场上的连接怪兽数量的攻击。这个效果发动的回合，那只怪兽以外的自己怪兽不能攻击。'),
(73287067, 'Link Burst', '连接爆发', 'リンク・バースト', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己场上1只连接怪兽和对方场上1只怪兽为对象才能发动。那些怪兽破坏。那之后，自己从卡组抽1张。'),
(30342076, 'Link Decoder', '连接解码者', 'リンク・デコーダー', 'Link Monster', 'Cyberse', 'DARK', NULL, 300, NULL, '4星以下的电子界族怪兽1只 这个卡名的效果1回合只能使用1次。 ①：作为原本攻击力是2300以上的电子界族连接怪兽的连接素材让这张卡被送去墓地的场合才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(48068378, 'Link Devotee', '连接信徒', 'リンク・ディヴォーティー', 'Link Monster', 'Cyberse', 'EARTH', NULL, 500, NULL, '4星以下的电子界族怪兽1只 这个卡名的②的效果1回合只能使用1次。 ①：这张卡特殊召唤成功的场合发动。这个回合，自己不能把连接3以上的连接怪兽连接召唤。 ②：互相连接状态的这张卡被解放的场合才能发动。在自己场上把2只「连接衍生物」（电子界族·光·1星·攻/守0）特殊召唤。'),
(32995276, 'Link Disciple', '连接门徒', 'リンク・ディサイプル', 'Link Monster', 'Cyberse', 'LIGHT', NULL, 500, NULL, '4星以下的电子界族怪兽1只 这个卡名的效果1回合只能使用1次。 ①：把这张卡所连接区1只怪兽解放才能发动。自己从卡组抽1张，那之后选1张手卡回到卡组最下面。'),
(73275815, 'Link Hole', '连接洞', 'リンケージ・ホール', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上有连接4以上的连接怪兽存在的场合才能发动。选最多有自己场上的连接3以上的连接怪兽数量的对方场上的怪兽破坏。'),
(65100616, 'Link Infra-Flier', '连接基架飞行器', 'リンク・インフライヤー', 'Effect Monster', 'Cyberse', 'WIND', 2, NULL, 1800, '这个卡名的①的方法的特殊召唤1回合只能有1次。 ①：这张卡可以从手卡往作为场上的连接怪兽所连接区的自己场上特殊召唤。'),
(28827503, 'Link into the VRAINS!', '进入VRAINS！', 'Into the VRAINS！', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从手卡把1只怪兽效果无效特殊召唤，用包含那只怪兽的自己场上的怪兽为素材作连接召唤。那次连接召唤不会被无效化，在那次连接召唤成功时对方不能把魔法·陷阱·怪兽的效果发动。 ②：这张卡在墓地存在的状态，自己场上的连接怪兽被战斗·效果破坏的场合，把这张卡除外才能发动。从自己墓地选原本种族和那只怪兽相同的1只怪兽加入手卡。'),
(68957925, 'Link Party', '连接茶会', 'リンク・パーティー', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：场上的连接怪兽的原本属性种类数量对应的以下适用。 ●1种类：自己场上的连接怪兽的攻击力上升500。 ●2种类：对方场上的连接怪兽的攻击力下降1000。 ●3种类：自己回复1500基本分。 ●4种类：给与对方2000伤害。 ●5种类：自己从卡组把1只攻击力2500以上的怪兽特殊召唤。 ●6种类：对方场上的攻击力3000以下的怪兽全部破坏。'),
(27664101, 'Link Restart', '连接重启', 'リンク・リスタート', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '①：给与自己伤害的怪兽的效果·魔法·陷阱卡发动时才能发动。那个发动无效，从自己墓地选1只连接怪兽特殊召唤。'),
(98978921, 'Link Spider', '连接蜘蛛', 'リンク・スパイダー', 'Link Monster', 'Cyberse', 'EARTH', NULL, 1000, NULL, '通常怪兽1只 ①：1回合1次，自己主要阶段才能发动。从手卡把1只4星以下的通常怪兽在作为这张卡所连接区的自己场上特殊召唤。'),
(23331400, 'Link Streamer', '连接流式鸟', 'リンク・ストリーマー', 'Effect Monster', 'Cyberse', 'LIGHT', 4, 1600, 1800, '这个卡名的效果1回合只能使用1次。 ①：这张卡已在怪兽区域存在的状态，自己场上有电子界族怪兽召唤·特殊召唤时才能发动。在自己场上把1只「数据衍生物」（电子界族·光·1星·攻/守0）特殊召唤。'),
(55034079, 'Link Turret', '连接死亡炮塔', 'リンク・デス・ターレット', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：作为这张卡的发动时的效果处理，给这张卡放置4个指示物。 ②：每次自己受到战斗伤害给这张卡放置1个指示物。 ③：自己主要阶段2，把这张卡1个指示物取除，以自己墓地1只「弹丸」怪兽为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽的效果无效化，从场上离开的场合除外。这个效果发动的回合，自己不是暗属性连接怪兽不能从额外卡组特殊召唤。'),
(63092423, 'Linkbelt Wall Dragon', '弹带城壁龙', '弾帯城壁龍', 'Effect Monster', 'Dragon', 'EARTH', 6, NULL, 2100, '这张卡不能通常召唤，用这张卡的效果才能特殊召唤。 ①：自己连接召唤成功时才能发动。这张卡从手卡特殊召唤，给这张卡放置2个指示物。 ②：双方不能把持有比这张卡的指示物数量多的数量的连接标记的怪兽连接召唤，连接怪兽以外的怪兽不能攻击。 ③：怪兽连接召唤的场合发动。这张卡2个指示物取除。 ④：自己·对方的准备阶段发动。给这张卡放置1个指示物。'),
(54635100, 'Linkerbell', '叮当铃连接星', 'リンクルベル', 'Link Monster', 'Fairy', 'EARTH', NULL, 1500, NULL, '怪兽2只 这张卡的连接召唤不在自己的额外卡组的数量比对方多3张以上的场合不能进行。'),
(68295149, 'Linkmail Archfiend', '连接邮件盔甲恶魔', 'リンクメイル・デーモン', 'Link Monster', 'Cyberse', 'DARK', NULL, 2800, NULL, '包含仪式·融合·同调·超量怪兽其中任意种的怪兽2只以上 ①：这张卡特殊召唤成功的场合，以自己的场上·墓地1只仪式·融合·同调·超量怪兽为对象才能发动。对方场上的全部怪兽的攻击力直到回合结束时下降作为对象的怪兽的攻击力数值。 ②：从额外卡组特殊召唤的自己场上的怪兽不会成为对方怪兽的效果的对象。 ③：这张卡被战斗·效果破坏的场合，可以作为代替把自己墓地1只仪式·融合·同调·超量怪兽除外。'),
(85243784, 'Linkross', '连接十字', 'リンクロス', 'Link Monster', 'Cyberse', 'LIGHT', NULL, 900, NULL, '连接2以上的连接怪兽1只 这个卡名的效果1回合只能使用1次。 ①：这张卡连接召唤成功的场合才能发动。把最多有那只作为连接素材的连接怪兽的连接标记数量的「连接衍生物」（电子界族·光·1星·攻/守0）在自己场上特殊召唤。这个效果的发动后，直到回合结束时自己不能把「连接衍生物」作为连接素材。'),
(35595518, 'Linkslayer', '连接山猫屠杀者', 'リンクスレイヤー', 'Effect Monster', 'Cyberse', 'EARTH', 5, 2000, 600, '①：自己场上没有怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：1回合1次，把最多2张手卡丢弃，以丢弃数量的场上的魔法·陷阱卡为对象才能发动。那些卡破坏。'),
(61168637, 'Linkslayer @Ignister', '连接山猫屠杀者＠伊格尼斯者', 'リンクスレイヤー＠イグニスター', 'Effect Monster', 'Cyberse', 'DARK', 5, 2000, 600, '这个卡名的①②的效果1回合各能使用1次。 ①：把自己场上的电子界族怪兽作为「@火灵天星」连接怪兽的连接素材的场合，手卡的这张卡也能作为连接素材。 ②：这张卡作为连接素材送去墓地的场合，丢弃1张手卡，以场上1张魔法·陷阱卡为对象才能发动（场上的这张卡为素材的场合，这个效果的对象可以变成2张）。那张卡破坏。'),
(41999284, 'Linkuriboh', '连接库里波', 'リンクリボー', 'Link Monster', 'Cyberse', 'DARK', NULL, 300, NULL, '1星怪兽1只 这个卡名的②的效果1回合只能使用1次。 ①：对方怪兽的攻击宣言时，把这张卡解放才能发动。那只对方怪兽的攻击力直到回合结束时变成0。 ②：自己·对方回合，这张卡在墓地存在的场合，把自己场上1只1星怪兽解放才能发动。这张卡特殊召唤。'),
(4611269, 'Lion Alligator', '狮头短吻鳄', 'ライオ・アリゲーター', 'Effect Monster', 'Reptile', 'WATER', 4, 1900, 200, '自己场上有这张卡以外的爬虫类族怪兽存在的场合，自己场上存在的爬虫类族怪兽向守备表示怪兽攻击时，若攻击力超过那个守备力，给与对方基本分那个数值的战斗伤害。'),
(61692648, 'Lionhearted Locomotive', '勇气机关车 勇敢噗噗', '勇気機関車ブレイブポッポ', 'Effect Monster', 'Machine', 'EARTH', 4, 2400, 2100, '①：这张卡的攻击宣言时发动。这张卡的攻击力直到伤害步骤结束时变成原本攻击力的一半。'),
(93108297, 'Liquid Beast', '液体兽', 'リクイド・ビースト', 'Normal Monster', 'Aqua', 'WATER', 3, 950, 800, '粘粘糊糊的融化，能在水里自由移动的液态生命体。'),
(55210709, 'Lisark', '青玉眼怪', 'サファイヤ・リサーク', 'Normal Monster', 'Beast', 'EARTH', 4, 1300, 1300, '蓝宝石眼睛的野兽。制造幻影，趁敌人混乱的时候进行攻击。'),
(8955148, 'Litmus Doom Ritual', '石蕊的死仪式', 'リトマスの死儀式', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '「石蕊之死剑士」的降临必需。这个卡名的②的效果1回合只能使用1次。 ①：从自己的手卡·场上把等级合计直到8以上的怪兽解放，从手卡把「石蕊之死剑士」仪式召唤。 ②：这张卡在墓地存在的场合，以自己墓地1只「石蕊之死剑士」为对象才能发动。墓地的这张卡和作为对象的怪兽合计2张加入卡组洗切。那之后，自己从卡组抽1张。'),
(72566043, 'Litmus Doom Swordsman', '石蕊之死剑士', 'リトマスの死の剣士', 'Ritual Effect Monster', 'Warrior', 'DARK', 8, NULL, NULL, '「石蕊的死仪式」降临。 ①：这张卡只要在怪兽区域存在，不受陷阱卡的效果影响，不会被战斗破坏。 ②：陷阱卡在场上表侧表示存在的场合，这张卡的攻击力·守备力上升3000。 ③：仪式召唤的这张卡被对方破坏的场合，以自己或者对方的墓地1张陷阱卡为对象才能发动。那张卡在自己的魔法与陷阱区域盖放。'),
(68658728, 'Little Chimera', '小奇美拉', 'リトル・キメラ', 'Effect Monster', 'Beast', 'FIRE', 2, 600, 550, '只要这张卡在场上表侧表示存在，场上的炎属性怪兽的攻击力上升500，水属性怪兽的攻击力下降400。'),
(42625254, 'Little D', '小霸王龙', 'ベビー・ティーレックス', 'Normal Monster', 'Dinosaur', 'EARTH', 3, 1100, 700, '恐龙的孩子。性格极其凶暴。'),
(45939611, 'Little Fairy', '小妖精', 'リトル・フェアリー', 'Effect Monster', 'Fairy', 'LIGHT', 3, 800, 800, '自己的主要阶段时把1张手卡送去墓地才能发动。这张卡的等级上升1星。这个效果1回合可以使用最多2次。'),
(73702909, 'Little Trooper', '小骑兵', 'リトルトルーパー', 'Effect Monster', 'Warrior', 'EARTH', 1, 900, 500, '这张卡被战斗破坏的场合，可以从卡组把1只2星以下的战士族怪兽里侧守备表示特殊召唤。'),
(90790253, 'Little-Winguard', '小翼守卫', 'リトル・ウィンガード', 'Effect Monster', 'Warrior', 'WIND', 4, 1400, 1800, '这张卡在自己的结束阶段时可以变更表示形式1次。'),
(35487920, 'Live☆Twin Channel', '直播☆双子 频道', 'Live☆Twin チャンネル', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己或者对方的怪兽的攻击宣言时，把自己场上1只「姬丝基勒」怪兽或者「璃拉」怪兽解放才能发动。那次攻击无效。 ②：自己·对方的结束阶段，以自己墓地1只「姬丝基勒」怪兽或者「璃拉」怪兽为对象才能发动。那只怪兽回到卡组。自己场上没有怪兽存在的场合，也能不回到卡组加入手卡。'),
(8083925, 'Live☆Twin Home', '直播☆双子 实况入口', 'Live☆Twin エントランス', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：丢弃1张手卡才能发动。从卡组把1只「姬丝基勒」怪兽或「璃拉」怪兽特殊召唤。这张卡的发动后，直到回合结束时自己不是「邪恶★双子」怪兽不能从额外卡组特殊召唤。'),
(36326160, 'Live☆Twin Ki-sikil', '直播☆双子 姬丝吉尔', 'Live☆Twin キスキル', 'Effect Monster', 'Cyberse', 'LIGHT', 2, 500, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤的场合，若自己场上没有其他怪兽存在则能发动。从手卡·卡组把1只「璃拉」怪兽特殊召唤。 ②：只要这张卡在怪兽区域存在，每次对方怪兽攻击宣言，自己回复500基本分。'),
(54257392, 'Live☆Twin Ki-sikil Frost', '直播☆双子 姬丝吉尔冰霜', 'Live☆Twin キスキル・フロスト', 'Effect Monster', 'Aqua', 'LIGHT', 2, 500, NULL, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：自己场上有「璃拉」怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：对方用卡的效果从卡组把卡加入手卡的场合，若自己场上有「邪恶★双子」怪兽存在，把墓地的这张卡除外才能发动。自己抽1张。'),
(73810864, 'Live☆Twin Lil-la', '直播☆双子 璃拉', 'Live☆Twin リィラ', 'Effect Monster', 'Cyberse', 'DARK', 2, 500, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤的场合，若自己场上没有其他怪兽存在则能发动。从手卡·卡组把1只「姬丝基勒」怪兽特殊召唤。 ②：只要这张卡在怪兽区域存在，对方若不支付500基本分则不能攻击宣言。'),
(82699999, 'Live☆Twin Lil-la Sweet', '直播☆双子 璃拉甜心', 'Live☆Twin リィラ・スウィート', 'Effect Monster', 'Spellcaster', 'DARK', 2, 500, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：对方连锁自己的「直播☆双子」卡的效果的发动把魔法·陷阱·怪兽的效果发动时，把这张卡从手卡丢弃才能发动。那个对方的效果无效。 ②：这张卡在墓地存在，自己场上有「姬丝基勒」怪兽存在的场合才能发动。这张卡特殊召唤。只要这个效果特殊召唤的这张卡在怪兽区域表侧表示存在，自己不是恶魔族怪兽不能从额外卡组特殊召唤。'),
(81078880, 'Live☆Twin Lil-la Treat', '直播☆双子 璃拉讨糖', 'Live☆Twin リィラ・トリート', 'Effect Monster', 'Zombie', 'DARK', 2, 500, NULL, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：自己场上有「姬丝基勒」怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：「邪恶★双子」怪兽的战斗让自己或对方受到战斗伤害时，把墓地的这张卡除外，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力下降那次战斗伤害的数值。'),
(37582948, 'Live☆Twin Sunny''s Snitch', '直播☆双子 麻烦桑', 'Live☆Twin トラブルサン', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：作为这张卡的发动时的效果处理，可以从卡组把1只「直播☆双子」怪兽加入手卡。 ②：只要自己场上有「邪恶★双子」怪兽存在，每次对方把怪兽召唤·特殊召唤，自己回复200基本分，给与对方200伤害。'),
(34959756, 'Living Fossil', '活化石', 'リビング・フォッシル', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己墓地1只4星以下的怪兽为对象才能把这张卡发动。那只怪兽特殊召唤，把这张卡装备。这个效果特殊召唤的怪兽从场上离开的场合除外。这张卡从场上离开时那只怪兽除外。 ②：装备怪兽的攻击力·守备力下降1000，效果无效化。'),
(34320307, 'Living Vase', '有生命的花瓶', '命ある花瓶', 'Normal Monster', 'Plant', 'EARTH', 3, 900, 1100, '利用花散发花粉并咬向对方的活花瓶。'),
(20831168, 'Lizard Soldier', '蜥蜴兵', 'リザード兵', 'Normal Monster', 'Dragon', 'WIND', 3, 1100, 800, '从龙派生出来的兽人种。在龙族之中体形小而敏捷。战略性丰富。'),
(40666140, 'Ljosalf of the Nordic Alfar', '极星灵 光精灵', '極星霊リョースアールヴ', 'Effect Monster', 'Spellcaster', 'LIGHT', 4, 1400, 1200, '这张卡召唤成功时，选择这张卡以外的自己场上表侧表示存在的1只怪兽才能发动。选择的怪兽的等级以下的1只名字带有「极星」的怪兽从手卡特殊召唤。'),
(25801745, 'Lo, the Prayers of the Voiceless Voice', '肃声之祈祷者 律', '粛声の祈り手ロー', 'Effect Monster', 'Fairy', 'LIGHT', 1, 50, 2050, '这个卡名的①③的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从卡组把1张「肃声」永续魔法·永续陷阱卡在自己的魔法与陷阱区域表侧表示放置。 ②：战士族·龙族而光属性的仪式怪兽1只仪式召唤的场合，可以由这1张卡作为仪式召唤需要的数值的解放使用。 ③：这张卡在墓地存在的状态，自己场上有战士族·龙族而光属性的仪式怪兽特殊召唤的场合才能发动。这张卡特殊召唤。'),
(64681263, 'Localized Tornado', '局地性大飓风', '局地的大ハリケーン', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己的手卡·墓地存在的卡全部回到持有者卡组洗切。'),
(52346240, 'Lock Cat', '锁猫', 'ロックキャット', 'Effect Monster', 'Beast', 'EARTH', 3, 1200, 1000, '这张卡召唤成功时，可以选择自己墓地存在的1只1星的兽族怪兽表侧守备表示特殊召唤。这个效果特殊召唤的怪兽的效果无效化。'),
(37310367, 'Lockout Gardna', '封锁守卫者', 'ロックアウト・ガードナー', 'Effect Monster', 'Cyberse', 'EARTH', 3, 1000, 1000, '①：对方怪兽的直接攻击宣言时才能发动。这张卡从手卡攻击表示特殊召唤。这个效果特殊召唤的这张卡在这个回合不会被战斗破坏。 ②：只以自己场上的电子界族怪兽1只为对象的对方场上的怪兽的效果发动时才能发动。那只自己的电子界族怪兽和那只对方怪兽的效果直到回合结束时无效化。'),
(38354937, 'Locomotion R-Genex', '真次代机・黑铁汽机', 'レアル・ジェネクス・クロキシアン', 'Synchro Monster', 'Machine', 'DARK', 9, 2500, 2000, '「次世代」调整＋调整以外的暗属性怪兽1只以上 ①：这张卡同调召唤的场合发动。得到对方场上1只等级最高的怪兽的控制权。'),
(18478530, 'Loge''s Flame', '洛戈之焰', 'ローゲの焔', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：只要这张卡在魔法与陷阱区域存在并在自己场上有「女武神」怪兽存在，攻击力2000以下的对方怪兽不能攻击。 ②：这张卡被对方的效果破坏的场合才能发动。从手卡·卡组把1只5星以上的「女武神」怪兽特殊召唤。'),
(2116237, 'Loka Samsara', '世坏轮回', '世壊輪廻', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：把自己场上1只表侧表示的「维萨斯-斯塔弗罗斯特」直到结束阶段除外才能发动。把1只攻击力3000的「哈特」怪兽无视召唤条件从额外卡组特殊召唤。这个效果特殊召唤的怪兽只能有1次把效果发动，结束阶段里侧除外。 ②：这张卡在墓地存在的状态，对方从额外卡组把怪兽特殊召唤的场合才能发动。这张卡加入手卡。'),
(67098114, 'Loki, Lord of the Aesir', '极神皇 洛基', '極神皇ロキ', 'Synchro Monster', 'Spellcaster', 'DARK', 10, 3300, 3000, '名字带有「极星灵」的调整＋调整以外的怪兽2只以上 1回合1次，自己的战斗阶段中对方把魔法·陷阱卡发动时，可以把那个发动无效并破坏。场上表侧表示存在的这张卡被对方破坏送去墓地的场合，那个回合的结束阶段时可以把自己墓地存在的1只名字带有「极星灵」的调整从游戏中除外，这张卡从墓地特殊召唤。这个效果特殊召唤成功时，可以选择自己墓地存在的1张陷阱卡加入手卡。'),
(93192592, 'Lollipo★Yummy Way', '棒棒喵★黯蜜味', 'ロリポー★ヤミーウェイ', 'Synchro Tuner Monster', 'Beast', 'LIGHT', 2, 1200, 1200, '调整＋调整以外的怪兽1只 这张卡同调召唤的场合，可以把自己场上1只连接1怪兽当作1星调整使用。这个卡名的①②的效果1回合各能使用1次。 ①：这张卡同调召唤的场合才能发动。从自己墓地把2只「味美喵」怪兽效果无效特殊召唤。 ②：对方把魔法·陷阱·怪兽的效果发动时，让这张卡回到额外卡组才能发动。从自己墓地把最多2只「味美喵」怪兽特殊召唤。'),
(4215180, 'Lollipo☆Yummy', '棒棒喵☆黯蜜', 'ロリポー☆ヤミー', 'Effect Monster', 'Beast', 'LIGHT', 1, 600, 1200, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：连接1怪兽或者2星同调怪兽在自己场上存在的场合，这张卡可以从手卡特殊召唤。 ②：这张卡召唤·特殊召唤的场合，以对方墓地1张卡为对象才能发动。那张卡回到卡组。同调怪兽的效果特殊召唤的场合，也能作为代替把作为对象的卡除外。'),
(82452993, 'Lone Wolf', '孤高的格斗家', '孤高の格闘家', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '自己场上只有「格斗鼠 吱助」「武僧战士」「武僧大师」内的其中1只存在的场合才能发动。这只怪兽不会被战斗破坏，不会受到对方怪兽的效果影响。'),
(48686504, 'Lonefire Blossom', '孤燃花', 'ローンファイア・ブロッサム', 'Effect Monster', 'Plant', 'FIRE', 3, 500, 1400, '①：1回合1次，把自己场上1只表侧表示的植物族怪兽解放才能发动。从卡组把1只植物族怪兽特殊召唤。'),
(76145142, 'Longirsu, the Orcust Orchestrator', '自鸣天琴・朗基尔苏', 'オルフェゴール・ロンギルス', 'Link Monster', 'Machine', 'DARK', NULL, 2500, NULL, '包含「自奏圣乐」怪兽的效果怪兽2只以上 这个卡名的②的效果1回合只能使用1次。 ①：连接状态的这张卡不会被效果破坏。 ②：以自己的除外状态的2只机械族怪兽为对象才能发动（这个效果发动的回合，这张卡不能攻击）。那些怪兽回到卡组。那之后，可以把1只连接状态的对方怪兽送去墓地。'),
(300302034, 'Looking into the Future', NULL, NULL, 'Skill Card', 'Aster Phoenix', NULL, NULL, NULL, NULL, NULL),
(7852509, 'Loop of Destruction', '破坏轮回', '破壊輪廻', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：这张卡只要在魔法与陷阱区域存在，卡名当作「破坏轮」使用。 ②：1回合1次，场上的怪兽被效果破坏的场合，以场上1只怪兽为对象才能发动。那只怪兽破坏，双方受到500伤害。'),
(94183877, 'Loptr, Shadow of the Generaider Bosses', '创王之影 洛普托尔', '王の影 ロプトル', 'Effect Monster', 'Fairy', 'FIRE', 4, 1500, 1500, '这个卡名的③的效果1回合只能使用1次。 ①：「王战之影 洛普特」在自己场上只能有1只表侧表示存在。 ②：自己场上的「王战」怪兽的攻击力·守备力在对方回合内上升1000。 ③：自己·对方的主要阶段，把自己场上1只「王战」怪兽解放才能发动。和那只怪兽卡名不同的1只9星「王战」怪兽从卡组特殊召唤。'),
(35514096, 'Lord British Space Fighter', '罗德不列颠号', 'ロードブリティッシュ', 'Effect Monster', 'Machine', 'LIGHT', 4, 1200, 800, '这张卡战斗破坏对方怪兽的场合，从下面效果选择1个发动。 ●只有1次可以继续攻击。 ●选择场上盖放的1张卡破坏。 ●在自己场上把1只「分机衍生物」（机械族·光·4星·攻/守1200）特殊召唤。'),
(8910971, 'Lord Gaia the Fierce Knight', '暗黑骑士 盖亚王', '暗黒騎士ガイアロード', 'Effect Monster', 'Warrior', 'EARTH', 7, 2300, 2100, '①：只有对方场上才有怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：1回合1次，比这张卡攻击力高的怪兽在对方场上特殊召唤的场合才能发动。这张卡的攻击力直到回合结束时上升700。'),
(17985575, 'Lord of D.', '龙之主宰－龙的支配者', 'ロード・オブ・ドラゴン－ドラゴンの支配者－', 'Effect Monster', 'Spellcaster', 'DARK', 4, 1200, 1100, '①：只要这张卡在怪兽区域存在，双方不能把场上的龙族怪兽作为效果的对象。'),
(9822220, 'Lord of the Heavenly Prison', '天狱之王', '天獄の王', 'Effect Monster', 'Rock', 'DARK', 10, 3000, 3000, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：自己主要阶段才能发动。手卡的这张卡直到对方回合结束时公开。这个效果公开期间，场上的里侧表示卡不会被效果破坏。 ②：盖放的魔法·陷阱卡发动的场合才能发动。这张卡从手卡特殊召唤。以在手卡被公开中的状态把这个效果发动的场合，可以再从卡组把1张魔法·陷阱卡在自己场上盖放。那张卡在下个回合的结束阶段除外。'),
(99510761, 'Lord of the Lamp', '神灯魔人', 'ランプの魔人', 'Normal Monster', 'Fiend', 'DARK', 4, 1400, 1200, '从神灯里出现的魔灵，服从召唤者的意志。'),
(59829423, 'Lord of the Missing Barrows', '至天魔王 失落的巴勒斯', '至天の魔王ミッシング・バロウズ', 'Effect Monster', 'Fiend', 'LIGHT', 10, 3100, 2900, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡可以从自己墓地把卡3种类（怪兽·魔法·陷阱）各1张除外，从手卡特殊召唤。 ②：这张卡从手卡特殊召唤的场合才能发动。把1只怪兽和2张魔法·陷阱卡从对方的场上·墓地除外。'),
(19025379, 'Lord of the Red', '真红王', 'ロード・オブ・ザ・レッド', 'Ritual Effect Monster', 'Dragon', 'FIRE', 8, 2400, 2100, '「真红眼转生」降临。 ①：1回合1次，自己或者对方把「真红王」以外的魔法·陷阱·怪兽的效果发动时，以场上1只怪兽为对象才能发动。那只怪兽破坏。 ②：1回合1次，自己或者对方把「真红王」以外的魔法·陷阱·怪兽的效果发动时，以场上1张魔法·陷阱卡为对象才能发动。那张卡破坏。'),
(44466810, 'Lord of the Tachyon Galaxy', '快子时空银河霸主', 'ロード・オブ・ザ・タキオンギャラクシー', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。自己场上有「银河眼时空龙」怪兽存在的场合，这张卡的发动从手卡也能用。 ①：自己·对方的战斗阶段，把自己场上的「银河眼」超量怪兽1个超量素材取除才能发动（自己场上有「混沌No.」怪兽存在的场合，这张卡的发动和效果不会被无效化）。让这个回合召唤·特殊召唤的对方场上的怪兽全部回到卡组。'),
(81618817, 'Lord of Zemia', '杰米亚之神', 'ゼミアの神', 'Normal Monster', 'Fiend', 'DARK', 4, 1300, 1000, '善于欺骗对方、诱惑其加入破灭之路的邪恶之神。'),
(40320754, 'Lord Poison', '毒根王', 'ロードポイズン', 'Effect Monster', 'Plant', 'WATER', 4, 1500, 1000, '这张卡被战斗破坏送去墓地时，从自己墓地里特殊召唤1只「毒根王」以外的植物族怪兽上场。'),
(50699850, 'Loris, Lady of Lament', '恶之魔娘 萝丽斯', '悪魔嬢ロリス', 'Effect Monster', 'Fiend', 'DARK', 3, 1500, 500, '这个卡名的①②的效果1回合各能使用1次。 ①：从自己墓地的卡以及除外的自己的卡之中以3张或者6张通常陷阱卡为对象才能发动。那些卡用喜欢的顺序回到卡组下面。那之后，回去的卡每有3张，自己从卡组抽1张。 ②：这张卡以外的怪兽被解放的场合或者对方的效果让通常陷阱卡被送去自己墓地的场合，以自己墓地1张通常陷阱卡为对象才能发动。那张卡在自己场上盖放。'),
(24348804, 'Lose 1 Turn', '休息一回', '一回休み', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '特殊召唤的怪兽不在自己场上存在的场合才能把这张卡发动。 ①：只要这张卡在魔法与陷阱区域存在，特殊召唤的怪兽直到那个回合结束时效果无效化。 ②：效果怪兽攻击表示特殊召唤的场合把这个效果发动。那些怪兽变成守备表示。'),
(72453068, 'Loss Time', '伤停补时', 'ロスタイム', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：对方基本分是4000以上的场合，自己基本分变成比对方少1000的数值。'),
(95231062, 'Lost Blue Breaker', '失落之蓝破坏者', 'ロスト・ブルー・ブレイカー', 'Effect Monster', 'Sea Serpent', 'WATER', 3, 1400, NULL, '场上有这张卡以外的鱼族·海龙族·水族怪兽存在的场合把这张卡解放才能发动。选择场上1张魔法·陷阱卡破坏。'),
(45871897, 'Lost Guardian', '失落守护者', 'ロストガーディアン', 'Effect Monster', 'Rock', 'EARTH', 4, 100, -1, '这张卡原本的守备力，是自己除外的岩石族怪兽数×700。'),
(74003290, 'Lost Wind', '迷途之风', '迷い風', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以场上1只特殊召唤的表侧表示怪兽为对象才能发动。那只怪兽的效果无效化，原本攻击力变成一半。 ②：这张卡在墓地存在的状态，从对方的额外卡组有怪兽特殊召唤的场合才能发动。这张卡在自己场上盖放。这个效果盖放的这张卡从场上离开的场合除外。'),
(17228908, 'Lost World', '失落世界', 'ロストワールド', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：恐龙族以外的场上的怪兽的攻击力·守备力下降500。 ②：1回合1次，恐龙族怪兽召唤·特殊召唤的场合才能发动。在对方场上把1只「侏罗蛋衍生物」（恐龙族·地·1星·攻/守0）守备表示特殊召唤。 ③：只要对方场上有衍生物，对方不能把衍生物以外的场上的怪兽作为效果的对象。 ④：1回合1次，场上的通常怪兽被战斗·效果破坏的场合，可以作为代替把那个数量的自己的手卡·卡组的恐龙族怪兽破坏。'),
(61465001, 'Loud Cloud the Storm Serpent', '扰动骚蛇 响云蛇', '擾乱騒蛇ラウドクラウド', 'Effect Monster', 'Reptile', 'WATER', 5, NULL, 2000, '这张卡不能通常召唤。从自己墓地把炎属性和风属性的怪兽各1只除外的场合可以特殊召唤。这个卡名的①②的效果1回合各能使用1次。 ①：从自己墓地把1只炎属性怪兽除外，以对方场上1只怪兽为对象才能发动。那只怪兽破坏。这张卡的攻击力上升破坏的怪兽的原本攻击力数值。 ②：从自己墓地把1只风属性怪兽除外，以对方的魔法与陷阱区域1张卡为对象才能发动。那张卡破坏。'),
(2347656, 'Lovely Labrynth of the Silver Castle', '白银城的迷宫主・拉比丽斯', '白銀の城のラビュリンス', 'Effect Monster', 'Fiend', 'DARK', 8, 2900, 1900, '这个卡名的②③的效果1回合各能使用1次。 ①：对方不能对应自己的通常陷阱卡的发动把怪兽的效果发动。 ②：以自己墓地1张通常陷阱卡为对象才能发动。那张卡在自己场上盖放。这个效果盖放的卡在自己场上没有恶魔族怪兽存在的场合不能发动。 ③：自己的通常陷阱卡的效果让怪兽从场上离开的场合才能发动。对方的手卡·场上1张卡破坏（从手卡是随机选）。'),
(300302003, 'Low Blow', NULL, NULL, 'Skill Card', 'Andrew', NULL, NULL, NULL, NULL, NULL),
(70534340, 'Lubellion the Searing Dragon', '神炎龙 卢绯里昂', '神炎竜ルベリオン', 'Fusion Monster', 'Dragon', 'LIGHT', 8, 2500, 3000, '暗属性怪兽＋「阿不思的落胤」 这个卡名的效果1回合只能使用1次。 ①：这张卡融合召唤的场合，丢弃1张手卡才能发动。自己的场上·墓地·除外状态的怪兽作为融合素材回到卡组，把除「神炎龙 赫界龙」外的1只8星以下的融合怪兽融合召唤。这个回合，这张卡不能攻击，自己不是融合怪兽不能从额外卡组特殊召唤。'),
(45409943, 'Luce the Dusk''s Dark', '日暮之暗 露彻', NULL, 'Fusion Monster', 'Fiend', 'DARK', 8, 3500, 3000, '自己墓地的恶魔族·天使族怪兽×3 自己主要怪兽区域左端和右端的怪兽不会被效果破坏。 「日暮之暗 露彻」的以下效果1回合各能使用1次。 可以以对方场上1张卡为对象；从卡组把1只恶魔族·天使族怪兽送去墓地，那张卡破坏。 自己场上的其他卡被效果破坏的场合（伤害步骤除外）：可以以场上1张卡为对象；那张卡破坏。'),
(34968834, 'Lucent, Netherlord of Dark World', '暗黑界的鬼神 凯勒特', '暗黒界の鬼神 ケルト', 'Effect Monster', 'Fiend', 'DARK', 6, 2400, NULL, '①：这张卡被效果从手卡丢弃去墓地的场合发动。这张卡特殊召唤。被对方的效果丢弃的场合，再让自己可以从卡组把1只恶魔族怪兽在自己或者对方场上特殊召唤。'),
(58786132, 'Lucius the Shadow Vassal', '邪帝家臣鲁修斯', '邪帝家臣ルキウス', 'Effect Monster', 'Fiend', 'DARK', 1, 800, 1000, '「邪帝家臣 卢基乌斯」的①②的效果1回合各能使用1次。 ①：把自己墓地1只5星以上的怪兽除外才能发动。这张卡从手卡特殊召唤。这个回合，自己不能从额外卡组把怪兽特殊召唤。 ②：这张卡为上级召唤而被解放的场合才能发动。对方场上盖放的卡全部确认。对方不能对应这个效果的发动把魔法·陷阱·怪兽的效果发动。'),
(96012004, 'Lucky Chance', '幸运机会！', 'ラッキー・チャンス！', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '进行1次投掷硬币的效果怪兽的效果发动时对硬币的里表作猜测。猜中的场合，从自己卡组抽1张卡。'),
(82760689, 'Lucky Cloud', '宝札云', '宝札雲', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '发动回合中名字带有「云魔物」的同名怪兽有2只以上召唤·反转召唤·特殊召唤的场合，结束阶段时从自己卡组抽2张卡。'),
(34664411, 'Lucky Iron Axe', '幸运之铁斧', '幸運の鉄斧', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '①：装备怪兽的攻击力上升500。 ②：场上表侧表示存在的这张卡被对方的效果破坏送去墓地的场合发动。自己从卡组抽1张。'),
(67955331, 'Lucky Loan', '幸运的预借', '幸運の前借り', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己场上1只「占卜魔女」怪兽为对象才能发动。原本等级比那只怪兽低1星的1只魔法师族怪兽从手卡·卡组特殊召唤。这张卡的发动后，下次的自己回合中，自己不是魔法师族怪兽不能召唤·特殊召唤。'),
(68762510, 'Lucky Pied Piper', '幸运之吹笛人', '幸運の笛吹き', 'Gemini Monster', 'Fairy', 'WIND', 4, 1500, 500, '这张卡在墓地或者场上表侧表示存在的场合，当作通常怪兽使用。场上表侧表示存在的这张卡可以作当通常召唤使用的再度召唤，这张卡当作效果怪兽使用并得到以下效果。 ●这张卡战斗破坏对方怪兽送去墓地时，从自己卡组抽1张卡。'),
(36378044, 'Lucky Punch', '幸运拳', 'ラッキーパンチ', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '1回合1次，对方怪兽的攻击宣言时才能发动。进行3次投掷硬币，3次都是表的场合，自己从卡组抽3张卡。3次都是里的场合，这张卡破坏。此外，场上表侧表示存在的这张卡被破坏的场合，自己失去6000基本分。'),
(3985011, 'Lucky Trinket', '神圣能量', 'ホーリー・パワー', 'Normal Monster', 'Spellcaster', 'LIGHT', 2, 600, 800, '虽然摇摇晃晃的，但被圣之力保护着。'),
(39238953, 'Lullaby of Obedience', '天声之服从', '天声の服従', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：支付2000基本分，宣言1个怪兽卡名才能发动。对方把自身卡组确认，有宣言的怪兽的场合，把那之内的1只给双方确认从以下效果选择1个适用。 ●确认的卡加入把这张卡发动的玩家手卡。 ●确认的卡在把这张卡发动的玩家场上无视召唤条件攻击表示特殊召唤。'),
(57115864, 'Lumenize', '光子化', '光子化', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方怪兽的攻击宣言时才能发动。把1只对方怪兽的攻击无效，自己场上表侧表示存在的1只光属性怪兽的攻击力直到下次的自己的结束阶段时上升那只对方怪兽的攻击力数值。'),
(95503687, 'Lumina, Lightsworn Summoner', '光道召唤士 路米娜丝', 'ライトロード・サモナー ルミナス', 'Effect Monster', 'Spellcaster', 'LIGHT', 3, 1000, 1000, '①：1回合1次，丢弃1张手卡，以自己墓地1只4星以下的「光道」怪兽为对象才能发动。那只怪兽特殊召唤。 ②：自己结束阶段发动。从自己卡组上面把3张卡送去墓地。'),
(56166150, 'Lumina, Twilightsworn Shaman', '暮光道萨满 路米娜丝', 'トワイライトロード・シャーマン ルミナス', 'Effect Monster', 'Spellcaster', 'DARK', 3, 1000, 1000, '①：1回合1次，从自己的手卡·墓地把1只「光道」怪兽除外，以「暮光道萨满 露米娜丝」以外的自己的除外状态的1只「光道」怪兽为对象才能发动。那只怪兽特殊召唤。 ②：1回合1次，其他的自己的「光道」怪兽的效果发动的场合发动。从自己卡组上面把3张卡送去墓地。'),
(34834619, 'Luminous Dragon Ritual', '光子龙降临', '光子竜降臨', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '「光子龙之圣骑士」的降临必需。必须从自己的手卡·场上把等级合计直到4的怪兽解放。此外，自己的主要阶段时把墓地的这张卡从游戏中除外才能发动。等级合计直到4的自己墓地的怪兽从游戏中除外，从手卡把1只「光子龙之圣骑士」当作仪式召唤作特殊召唤。'),
(57482479, 'Luminous Soldier', '太阳之战士', '太陽の戦士', 'Effect Monster', 'Warrior', 'LIGHT', 5, 2100, 1400, '和暗属性的怪兽战斗的场合，伤害计算阶段这张卡的攻击力上升500。'),
(81777047, 'Luminous Spark', '光芒冲击', 'シャインスパーク', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '全部的光属性的怪兽攻击力上升500，守备力下降400。'),
(48444114, 'Luna Light Perfume', '月华香', '月光香', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己墓地1只「月光」怪兽为对象才能发动。那只怪兽特殊召唤。 ②：把墓地的这张卡除外，丢弃1张手卡才能发动。从卡组把1只「月光」怪兽加入手卡。'),
(48596760, 'Luna the Dark Spirit', '暗之精灵 露娜', '闇の精霊 ルーナ', 'Effect Monster', 'Fiend', 'DARK', 4, 1600, 1200, '这张卡不能通常召唤。从自己墓地把1只暗属性怪兽除外的场合可以特殊召唤。 ①：自己准备阶段发动。给与对方500伤害。'),
(11317977, 'Lunalight Black Sheep', '月光黑羊', '月光黒羊', 'Effect Monster', 'Beast-Warrior', 'DARK', 2, 100, 600, '①：可以把这张卡从手卡丢弃，从以下效果选择1个发动。 ●从自己墓地把「月光黑羊」以外的1只「月光」怪兽加入手卡。 ●从卡组把1张「融合」加入手卡。 ②：这张卡成为融合召唤的素材送去墓地的场合才能发动。从自己的额外卡组（表侧）·墓地把「月光黑羊」以外的1只「月光」怪兽加入手卡。'),
(11439455, 'Lunalight Blue Cat', '月光苍猫', '月光蒼猫', 'Effect Monster', 'Beast-Warrior', 'DARK', 4, 1600, 1200, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡特殊召唤成功的场合，以「月光苍猫」以外的自己场上1只「月光」怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时变成原本攻击力的2倍。 ②：场上的这张卡被战斗·效果破坏的场合才能发动。从卡组把1只「月光」怪兽特殊召唤。'),
(51777272, 'Lunalight Cat Dancer', '月光舞猫姬', '月光舞猫姫', 'Fusion Monster', 'Beast-Warrior', 'DARK', 7, 2400, 2000, '「月光」怪兽×2 ①：这张卡不会被战斗破坏。 ②：1回合1次，自己主要阶段1把这张卡以外的自己场上1只「月光」怪兽解放才能发动。这个回合，对方怪兽各有1次不会被战斗破坏，这张卡可以向全部对方怪兽各作2次攻击。 ③：这张卡的攻击宣言时发动。给与对方100伤害。'),
(94919024, 'Lunalight Crimson Fox', '月光红狐', '月光紅狐', 'Effect Monster', 'Beast-Warrior', 'DARK', 4, 1800, 600, '①：这张卡被效果送去墓地的场合，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时变成0。 ②：自己场上的「月光」怪兽为对象的魔法·陷阱·怪兽的效果发动时，把墓地的这张卡除外才能发动。那个发动无效，双方玩家回复1000基本分。'),
(14152693, 'Lunalight Emerald Bird', '月光翠鸟', '月光翠鳥', 'Effect Monster', 'Beast-Warrior', 'DARK', 4, 1200, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从手卡把1张「月光」卡送去墓地，自己抽1张。 ②：这张卡被效果送去墓地的场合，以除「月光翠鸟」外的自己的墓地·除外状态的1只4星以下的「月光」怪兽为对象才能发动。那只怪兽守备表示特殊召唤。这个效果特殊召唤的怪兽的效果无效化。'),
(87931906, 'Lunalight Fusion', '月光结合', '月光融合', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从自己的手卡·场上把「月光」融合怪兽卡决定的融合素材怪兽送去墓地，把那1只融合怪兽从额外卡组融合召唤。对方场上有从额外卡组特殊召唤的怪兽存在的场合自己的卡组·额外卡组的「月光」怪兽也能有最多1只作为融合素材。'),
(8379983, 'Lunalight Gold Leo', '月光金狮子', '月光金獅子', 'Effect Monster', 'Beast-Warrior', 'DARK', 4, 600, 1600, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从卡组把「月光金狮子」以外的1只「月光」怪兽加入手卡。那之后，选自己1张手卡丢弃。 ②：这张卡在怪兽区域存在的状态，「月光」怪兽被送去自己墓地的场合，以那之内的1只为对象才能发动（伤害步骤也能发动）。那只怪兽加入手卡。'),
(35618217, 'Lunalight Kaleido Chick', '月光彩雏', '月光彩雛', 'Effect Monster', 'Beast-Warrior', 'DARK', 4, 1400, 800, '这个卡名的②的效果1回合只能使用1次。 ①：1回合1次，从卡组·额外卡组把1只「月光」怪兽送去墓地才能发动。这个回合，把表侧表示的这张卡作为融合素材的场合，可以作为送去墓地的那只怪兽的同名卡来成为融合素材。 ②：这张卡被效果送去墓地的场合，以自己墓地1张「融合」为对象才能发动。那张卡加入手卡。 ③：这张卡被除外的场合才能发动。这个回合，对方在战斗阶段中不能把效果发动。'),
(24550676, 'Lunalight Leo Dancer', '月光舞狮子姬', '月光舞獅子姫', 'Fusion Monster', 'Beast-Warrior', 'DARK', 10, 3500, 3000, '「月光舞豹姬」＋「月光」怪兽×2 这张卡用以上记的卡为融合素材的融合召唤才能特殊召唤。 ①：场上的这张卡不会被对方的效果破坏，对方不能把场上的这张卡作为效果的对象。 ②：这张卡在同1次的战斗阶段中可以作2次攻击。 ③：1回合1次，这张卡向怪兽攻击的伤害步骤结束时才能发动。对方场上的特殊召唤的怪兽全部破坏。'),
(54701958, 'Lunalight Liger Dancer', '月光舞狮子神姬', '月光舞獅子神姫', 'Fusion Monster', 'Beast-Warrior', 'DARK', 12, 3800, 3500, '「月光舞狮子姬」＋「月光」怪兽×3 这张卡用以上记的卡为融合素材的融合召唤才能特殊召唤。 ①：这张卡只要在怪兽区域存在，不受「月光」卡以外的卡的效果影响。 ②：这张卡在同1次的战斗阶段中可以作2次攻击。 ③：自己·对方回合1次，从额外卡组把1只「月光」怪兽送去墓地才能发动。对方场上的特殊召唤的怪兽全部破坏。'),
(2344618, 'Lunalight Masquerade', '月光舞蹈会', '月光舞踏会', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡发动的回合的自己主要阶段才能发动。从卡组把1只「月光」怪兽送去墓地。 ②：自己把「月光」怪兽融合召唤的场合才能发动。自己的墓地·除外状态的1张「融合」加入手卡。那之后，可以选自己1张手卡丢弃。那个场合，这个回合，自己把「月光」怪兽融合召唤的场合只有1次，也能把自己墓地的怪兽除外作为融合素材。'),
(97165977, 'Lunalight Panther Dancer', '月光舞豹姬', '月光舞豹姫', 'Fusion Monster', 'Beast-Warrior', 'DARK', 8, 2800, 2500, '「月光舞猫姬」＋「月光」怪兽 这张卡用以上记的卡为融合素材的融合召唤才能从额外卡组特殊召唤。 ①：这张卡不会被对方的效果破坏。 ②：1回合1次，自己主要阶段1才能发动。这个回合，对方怪兽各有1次不会被战斗破坏，这张卡可以向全部对方怪兽各作2次攻击。 ③：这张卡战斗破坏对方怪兽时发动。这张卡的攻击力直到战斗阶段结束时上升200。'),
(81196066, 'Lunalight Perfume Dancer', '月光舞香姬', '月光舞香姫', 'Fusion Monster', 'Beast-Warrior', 'DARK', 6, 2000, 1500, '「月光」怪兽×2 这个卡名的①②③的效果1回合各能使用1次。 ①：这张卡融合召唤的场合才能发动。从卡组把1张「月华香」加入手卡。 ②：以自己场上1张其他的「月光」卡为对象才能发动。那张卡回到手卡·额外卡组。那之后，可以从手卡把1只「月光」怪兽特殊召唤。 ③：把墓地的这张卡除外才能发动。这个回合中，对方场上的怪兽的攻击力下降自身的原本守备力数值。'),
(48427163, 'Lunalight Purple Butterfly', '月光紫蝶', '月光紫蝶', 'Effect Monster', 'Beast-Warrior', 'DARK', 3, 1000, 1000, '「月光紫蝶」的②的效果1回合只能使用1次。 ①：把自己的手卡·场上的这张卡送去墓地，以自己场上1只「月光」怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时上升1000。 ②：把墓地的这张卡除外才能发动。从手卡把1只「月光」怪兽特殊召唤。');